// Hand-written: the client entry point. Everything else under src/ (except
// the files in src/.fernignore) is generated by Fern from the API contract.
// It adds only configuration (token, workspace, environment / base URL), an
// X-Idempotency-Key (Idempotency-Key) on the operations whose contract declares
// it, and safe retries for idempotent requests. It decides nothing else: the
// request is sent as given and the server's answer is returned unchanged.

import { IbeeClient } from "../Client.js";
import * as core from "../core/index.js";
import { IbeeEnvironment } from "../environments.js";
import { IbeeError } from "../errors/index.js";

export declare namespace Ibee {
    export interface Options extends Omit<IbeeClient.Options, "token" | "environment" | "baseUrl" | "fetcher"> {
        /** API token. Default: the `IBEE_API_TOKEN` (or `IBEE_TOKEN`) environment variable. */
        token?: string;
        /** Default `workspace_id` for every request. Default: `IBEE_WORKSPACE_ID`. */
        workspaceId?: string;
        /** `IbeeEnvironment.Production` (default) or `.Development`, or `"prod"` / `"dev"`. Default: `IBEE_ENV`. */
        environment?: string;
        /** Base URL; overrides `environment`. Default: `IBEE_API_URL`. */
        baseUrl?: string;
    }
}

/**
 * IBEE Solutions API client.
 *
 * ```ts
 * const ibee = new Ibee({ token: "ibee_prod_key_...", workspaceId: "710995" });
 * const vms = await ibee.cloudVms.listCloudVms();
 * ```
 */
export class Ibee extends IbeeClient {
    constructor(options: Ibee.Options = {}) {
        const env = readEnv();
        const {
            token: givenToken,
            workspaceId: givenWorkspaceId,
            environment,
            baseUrl: givenBaseUrl,
            ...rest
        } = options;
        const token = givenToken ?? env.IBEE_API_TOKEN ?? env.IBEE_TOKEN;
        if (!token) {
            throw new IbeeError({ message: "No API token: pass `token` or set IBEE_API_TOKEN." });
        }
        const baseUrl = resolveBaseUrl(givenBaseUrl ?? environment ?? env.IBEE_API_URL ?? env.IBEE_ENV);
        const workspaceId = givenWorkspaceId ?? env.IBEE_WORKSPACE_ID;
        // A supplier, so the token is not an enumerable string on the client (JSON.stringify, console.log).
        super({ ...rest, token: () => token, baseUrl, fetcher: ibeeFetcher(workspaceId) });
    }

    /** Any route, with the client's token and base URL. Never retried: the generated passthrough retries every method. */
    public override fetch(
        input: Request | string | URL,
        init?: RequestInit,
        requestOptions?: core.PassthroughRequest.RequestOptions,
    ): Promise<Response> {
        return super.fetch(input, init, { ...requestOptions, maxRetries: 0 });
    }
}

function readEnv(): Record<string, string | undefined> {
    const env = (globalThis as { process?: { env?: Record<string, string | undefined> } }).process?.env ?? {};
    const out: Record<string, string | undefined> = {};
    for (const name of ["IBEE_API_TOKEN", "IBEE_TOKEN", "IBEE_WORKSPACE_ID", "IBEE_ENV", "IBEE_API_URL"]) {
        out[name] = env[name]?.trim() || undefined;
    }
    return out;
}

const ENVIRONMENT_NAMES: Record<string, string> = {
    prod: IbeeEnvironment.Production,
    production: IbeeEnvironment.Production,
    dev: IbeeEnvironment.Development,
    development: IbeeEnvironment.Development,
};
const LOCAL_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]"]);

/** Absolute https URL (http only for localhost) without credentials, query or fragment. */
function resolveBaseUrl(value: string | undefined): string {
    const name = String(value ?? "").trim().toLowerCase();
    const raw = ENVIRONMENT_NAMES[name] ?? value ?? IbeeEnvironment.Production;
    let url: URL | undefined;
    try {
        url = new URL(raw);
    } catch {}
    const secure = url?.protocol === "https:" || (url?.protocol === "http:" && LOCAL_HOSTS.has(url.hostname));
    if (!url || !secure || url.username || url.password || url.search || url.hash || /[?#\s]/.test(raw)) {
        throw new IbeeError({
            message: `Invalid IBEE base URL '${raw}': use an absolute https URL (http only for localhost) without credentials, query or fragment.`,
        });
    }
    return raw.replace(/\/+$/, "");
}

// The 18 contract operations that require X-Idempotency-Key: every write on a
// cloud or GPU VM collection, VM or VM action.
const KEYED_ROUTE = /(^|\/)compute\/(cloud-vms|gpu-vms)(\/[^/]+(\/actions\/[^/]+)?)?\/?$/;
// Container Registry plan upgrade declares Idempotency-Key (not X-Idempotency-Key).
const UPGRADE_ROUTE = /(^|\/)container-registry\/registries\/[^/]+\/upgrade\/?$/;
// VM create is never retried.
const CREATE_ROUTE = /(^|\/)compute\/(cloud-vms|gpu-vms)\/?$/;
// Each GET of an identity's access mints a new secret ID, so it is not idempotent.
const NEVER_RETRY_ROUTE = /(^|\/)secret-store\/identities\/[^/]+\/access\/?$/;
// scripts/check-contract-calls.mjs checks these routes against contract/ibee-cloud.yaml.
const RETRY_STATUSES = new Set([429, 502, 503, 504]);
const MAX_RETRY_DELAY_MS = 30_000;

/**
 * Wraps the generated fetcher: fills the default workspace_id and a missing
 * X-Idempotency-Key (Idempotency-Key on Container Registry plan upgrade), and
 * retries idempotent requests (GET/HEAD, or a write that carries an idempotency
 * key; never VM create) on 429, 502, 503 and 504.
 */
function ibeeFetcher(workspaceId: string | undefined): core.FetchFunction {
    return async <R = unknown>(args: core.Fetcher.Args): Promise<core.APIResponse<R, core.Fetcher.Error>> => {
        const method = args.method.toUpperCase();
        const path = new URL(args.url).pathname;
        const queryParameters = { ...args.queryParameters };
        if (queryParameters.workspace_id == null && workspaceId) queryParameters.workspace_id = workspaceId;
        const headers: Record<string, unknown> = { ...args.headers };
        if (method !== "GET" && KEYED_ROUTE.test(path) && headers["x-idempotency-key"] == null) {
            headers["x-idempotency-key"] = newIdempotencyKey();
        }
        if (method === "POST" && UPGRADE_ROUTE.test(path) && headers["idempotency-key"] == null) {
            headers["idempotency-key"] = newIdempotencyKey();
        }
        const keyed =
            headers["x-idempotency-key"] != null ||
            headers["idempotency-key"] != null ||
            nonEmpty((args.body as Record<string, unknown> | undefined)?.idempotency_key) ||
            nonEmpty(queryParameters.idempotency_key);
        const retrySafe =
            method === "GET" || method === "HEAD"
                ? !NEVER_RETRY_ROUTE.test(path)
                : keyed && !(method === "POST" && CREATE_ROUTE.test(path));
        const maxRetries = args.maxRetries ?? 2;
        for (let attempt = 0; ; attempt += 1) {
            const response = await core.fetcher<R>({ ...args, headers, queryParameters, maxRetries: 0 });
            if (response.ok || !retrySafe || attempt >= maxRetries || !isRetryable(response.error)) {
                return response;
            }
            await sleep(retryDelayMs(attempt, response.rawResponse.headers), args.abortSignal);
        }
    };
}

function isRetryable(error: core.Fetcher.Error): boolean {
    return error.reason === "status-code" && RETRY_STATUSES.has(error.statusCode);
}

/** Retry-After (seconds or HTTP date) capped at 30 s, else 1 s * 2^attempt with +-10% jitter. */
function retryDelayMs(attempt: number, headers: Headers): number {
    const retryAfter = headers.get("retry-after");
    if (retryAfter) {
        const seconds = Number(retryAfter);
        const ms = Number.isFinite(seconds) ? seconds * 1000 : new Date(retryAfter).getTime() - Date.now();
        if (Number.isFinite(ms)) return Math.min(MAX_RETRY_DELAY_MS, Math.max(0, ms));
    }
    return Math.min(MAX_RETRY_DELAY_MS, 1000 * 2 ** attempt * (0.9 + Math.random() * 0.2));
}

function sleep(ms: number, signal?: AbortSignal): Promise<void> {
    return new Promise((resolve) => {
        if (signal?.aborted) return resolve();
        const timer = setTimeout(resolve, ms);
        signal?.addEventListener("abort", () => (clearTimeout(timer), resolve()), { once: true });
    });
}

function newIdempotencyKey(): string {
    const c = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto;
    if (c?.randomUUID) return c.randomUUID();
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (ch) => {
        const r = (Math.random() * 16) | 0;
        return (ch === "x" ? r : (r & 0x3) | 0x8).toString(16);
    });
}

const nonEmpty = (v: unknown): boolean => typeof v === "string" && v.trim() !== "";
